import json, re, datetime
ONES = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
TENS = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
AYLAR = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
GUNLER = ['Pazartesi', 'Salı', 'Çarşamba', 'Perşembe', 'Cuma', 'Cumartesi', 'Pazar']
SIRA = ['', 'birinci', 'ikinci', 'üçüncü', 'dördüncü']
CUR = [('TL', 'debtTL', 'Türk Lirası'), ('USD', 'debtUSD', 'Dolar'), ('EUR', 'debtEUR', 'Euro'), ('GBP', 'debtGBP', 'İngiliz Sterlini')]
FAIL_GEN = 'Şu anda işleminizi gerçekleştiremiyorum, sizi müşteri temsilcimize aktarıyorum.'
FAIL_WEEK = 'Şu anda hesap kesim tarihinizi değiştiremiyorum, sizi müşteri temsilcimize aktarıyorum.'
MENU = 'Sizi ana menüye yönlendiriyorum.'

def w3(n):
    p = []
    h, r = divmod(int(n), 100)
    if h:
        p.append('yüz' if h == 1 else ONES[h] + ' yüz')
    t, o = divmod(r, 10)
    if t:
        p.append(TENS[t])
    if o:
        p.append(ONES[o])
    return ' '.join(p)

def words(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    out = []
    for val, nm in ((10 ** 9, 'milyar'), (10 ** 6, 'milyon'), (1000, 'bin')):
        q, n = divmod(n, val)
        if q:
            out.append('bin' if (val == 1000 and q == 1) else words(q) + ' ' + nm)
    if n:
        out.append(w3(n))
    return ' '.join(out)

def num(x):
    try:
        return float(x)
    except Exception:
        return 0.0

def money(x, cur):
    c = int(round(abs(num(x)) * 100))
    a, k = divmod(c, 100)
    full = dict(TL='Türk Lirası', USD='Dolar', EUR='Euro', GBP='İngiliz Sterlini')[cur]
    unit = dict(TL='lira', USD='dolar', EUR='Euro', GBP='İngiliz Sterlini')[cur]
    sub = dict(TL='kuruş', USD='sent', EUR='sent', GBP='peni')[cur]
    if k == 0:
        return words(a) + ' ' + full
    return words(a) + ' ' + unit + ' ' + words(k) + ' ' + sub

def cop(t):
    t = t.rstrip()
    m = re.search(r'(\d+)$', t)
    tail = words(int(m.group(1))) if m else t
    low = tail.replace('I', 'ı').replace('İ', 'i').lower()
    vs = [ch for ch in low if ch in 'aeıioöuü']
    v = vs[-1] if vs else 'e'
    h = dict(a='ı', ı='ı', e='i', i='i', o='u', u='u', ö='ü', ü='ü')[v]
    dd = 't' if low[-1] in 'çfhkpsşt' else 'd'
    last = t.split()[-1]
    ap = "'" if (m or last[:1].isupper()) else ''
    return t + ap + dd + h + 'r'

def join_tr(xs):
    xs = [x for x in xs if x]
    if len(xs) <= 1:
        return ''.join(xs)
    return ', '.join(xs[:-1]) + ' ve ' + xs[-1]

def pdate(s):
    try:
        p = str(s).strip().split('.')
        return datetime.date(int(p[2]), int(p[1]), int(p[0]))
    except Exception:
        return None

def tdate(d):
    return str(d.day) + ' ' + AYLAR[d.month - 1] + ' ' + str(d.year)

def today_of(v):
    s = str(v.get('now') or '').strip()
    m = re.match(r'(\d{4})-(\d{1,2})-(\d{1,2})(?:[T ](\d{1,2}):(\d{2})(?::(\d{2}))?(?:\.\d+)?)?\s*(Z|[+-]\d{2}:?\d{2})?', s)
    if not m:
        return None, None
    dt = datetime.datetime(int(m.group(1)), int(m.group(2)), int(m.group(3)), int(m.group(4) or 0), int(m.group(5) or 0))
    tz = m.group(7)
    if tz:
        if tz == 'Z':
            off = 0
        else:
            sg = -1 if tz[0] == '-' else 1
            hh = tz[1:].replace(':', '')
            off = sg * (int(hh[:2]) * 60 + int(hh[2:4] or 0))
        dt = dt + datetime.timedelta(minutes=180 - off)
    return dt.date(), dt

def l4w(s):
    return ' '.join(DIG[int(ch)] for ch in str(s) if ch.isdigit())

BAD = ('talimat', 'yok say', 'ignore', 'instruction', 'prompt', 'önceki', 'previous', 'system', 'sistem')

def usable(nm):
    n = str(nm or '').strip()
    if not n or len(n) > 40 or len(n.split()) > 5:
        return False
    low = n.lower()
    if any(b in low for b in BAD):
        return False
    if re.search(r'[<>\[\]@#$%^*=|\\/]', n):
        return False
    return True

def load_cards(v):
    raw = v.get('cards_json')
    cards = None
    if isinstance(raw, list):
        cards = raw
    elif isinstance(raw, str) and raw.strip().startswith('['):
        try:
            cards = json.loads(raw)
        except Exception:
            cards = None
    if not cards:
        found = dict()
        for k, val in list(v.items()):
            mm = re.search(r'cards\.(\d+)\.(cardNumber|cardNumberLast4|productName|status|isMainCard)$', str(k))
            if mm:
                found.setdefault(int(mm.group(1)), dict())[mm.group(2)] = val
        cards = [found[i] for i in sorted(found)]
    return [c for c in cards if isinstance(c, dict) and c.get('cardNumber')]

def is_main(c):
    return str(c.get('isMainCard')).strip().lower() not in ('false', '0', 'no', 'n')

def elig(c):
    return is_main(c) and str(c.get('status') or 'A').strip().upper() == 'A'

def last4(c):
    return str(c.get('cardNumberLast4') or str(c.get('cardNumber'))[-4:])

def intro_of(c, cap=True):
    nm = str(c.get('productName') or '').strip()
    s = ('Sonu ' if cap else 'sonu ') + l4w(last4(c)) + ' ile biten'
    return s + (' ' + nm if usable(nm) else '')

def body_json(data):
    return json.dumps(dict(data=data, call=dict(ani='', lang='tr')), ensure_ascii=False)

def set_headers(cfg):
    h = cfg.get('headers') if isinstance(cfg.get('headers'), dict) else dict()
    h['Content-Type'] = 'application/json'
    h['Accept'] = 'application/json'
    cfg['headers'] = h

def env(result):
    result.pop('header', None)
    d = result.get('data')
    if not isinstance(d, dict):
        d = dict()
        result['data'] = d
    api = d.get('data') if isinstance(d.get('data'), dict) else None
    res = d.get('result') if isinstance(d.get('result'), dict) else dict()
    ok = api is not None and str(res.get('returnCode')) == '1' and str(result.get('status_code') or '200') == '200'
    return d, api, res, ok

def offer_text(v):
    em = str(v.get('email_state') or '') == 'has'
    wk = str(v.get('week_changed') or '') != 'yes'
    if em and wk:
        return 'Hesap kesim tarihinizi değiştirebilirim ya da ekstrenizi kayıtlı mail adresinize gönderebilirim.'
    if wk:
        return 'Hesap kesim tarihinizi değiştirebilirim.'
    if em:
        return 'Ekstrenizi kayıtlı mail adresinize gönderebilirim.'
    return ''

def to_digits(s):
    s = str(s or '').lower()
    if re.search(r'\d', s):
        return re.sub(r'\D', '', s)
    ones = dict(sıfır=0, bir=1, iki=2, üç=3, dört=4, beş=5, altı=6, yedi=7, sekiz=8, dokuz=9)
    tens = dict(on=1, yirmi=2, otuz=3, kırk=4, elli=5, altmış=6, yetmiş=7, seksen=8, doksan=9)
    toks = re.findall(r'[a-zçğıöşü]+', s)
    out = ''
    i = 0
    while i < len(toks):
        t = toks[i]
        if t in tens:
            if i + 1 < len(toks) and toks[i + 1] in ones and toks[i + 1] != 'sıfır':
                out += str(tens[t]) + str(ones[toks[i + 1]])
                i += 2
                continue
            out += str(tens[t]) + '0'
        elif t in ones:
            out += str(ones[t])
        i += 1
    return out

def parse_week(x):
    s = str(x if x is not None else '').strip().lower()
    m = re.search(r'[1-4]', s)
    if m:
        return int(m.group(0))
    for w, n in (('birinci', 1), ('ilk', 1), ('ikinci', 2), ('üçüncü', 3), ('dördüncü', 4), ('bir', 1), ('iki', 2), ('üç', 3), ('dört', 4)):
        if w in s:
            return n
    return 0

def build(api, card, v, want):
    td, dt = today_of(v)
    intro = intro_of(card)
    sd = pdate(api.get('statementDate'))
    due = pdate(api.get('lastPayDate'))
    nsd = pdate(api.get('nextStatementDate'))
    ndue = pdate(api.get('nextLastPayDate'))
    blocks = []
    for code, key, full in CUR:
        blk = api.get(key)
        if isinstance(blk, dict) and blk:
            blocks.append((code, full, blk))
    debt = [x for x in blocks if num(x[2].get('remainingDebt')) > 0]
    clear = [x[1] for x in blocks if num(x[2].get('remainingDebt')) <= 0]
    parts = []
    nodebt = False
    def due_sentence():
        if due is None:
            return ''
        if td is not None and due == td:
            return 'Borçlarınız için son ödeme tarihiniz bugündür.'
        return 'Borçlarınız için son ödeme tarihiniz ' + cop(tdate(due)) + '.'
    def total_sentence():
        am = [money(b.get('totalDebt'), code) for code, full, b in blocks if num(b.get('totalDebt')) > 0]
        if not am:
            return 'Kartınızın toplam borcu bulunmamaktadır.'
        return 'Kartınızın toplam borcu ' + cop(join_tr(am)) + '.'
    if sd is None:
        parts.append(intro + ' kartınızın henüz kesilmiş bir ekstresi bulunmadığı için ekstre borcunuz bulunmamaktadır.')
        nodebt = True
    elif not debt:
        nodebt = True
        s = intro + ' kartınızın ' + tdate(sd) + ' tarihli ekstresinden borcunuz bulunmamaktadır.'
        tl = [b for code, full, b in blocks if code == 'TL']
        g = num(tl[0].get('totalDebt')) if tl else 0.0
        if g > 0:
            s += ' Gelecek dönemler dahil toplam borcunuz ' + cop(money(g, 'TL')) + '.'
            dd = due if (due is not None and td is not None and due >= td) else (ndue or due)
            if dd is not None:
                s += ' Son ödeme tarihiniz ' + tdate(dd) + ' olacaktır.'
        else:
            s += ' Gelecek dönemler dahil de bir borcunuz bulunmamaktadır.'
        parts.append(s)
    else:
        cut_today = td is not None and ((sd is not None and td == sd) or (nsd is not None and td == nsd))
        passed = td is not None and due is not None and td > due and not cut_today
        if cut_today:
            parts.append(intro + ' kartınızın hesap kesim tarihi bugün, ekstreniz saat 00.00 itibarıyla kesilecek.')
            parts.append(total_sentence())
            dd = due if (sd is not None and td == sd) else ndue
            if dd is not None:
                parts.append('Son ödeme tarihiniz ' + tdate(dd) + ' olacaktır.')
        elif passed:
            parts.append(intro + ' kartınızın ' + tdate(sd) + ' tarihinde kesilen ekstresinin son ödeme tarihi ' + tdate(due) + ' idi, bu tarih geçti.')
            parts.append(total_sentence())
            tl = [b for code, full, b in blocks if code == 'TL']
            if tl and str(api.get('automaticPaymentFlag') or '').upper() == 'Y' and num(tl[0].get('remainAutomaticPaymentAmount')) > 0:
                parts.append('Otomatik ödeme talimatınızdan tahsil edilecek kalan tutar ' + cop(money(tl[0].get('remainAutomaticPaymentAmount'), 'TL')) + '.')
        elif want == 'sadece_son_odeme_tarihi' and due is not None:
            if td is not None and due == td:
                parts.append(intro + ' kartınız için borçlarınızın son ödeme tarihi bugündür.')
            else:
                parts.append(intro + ' kartınız için borçlarınızın son ödeme tarihi ' + cop(tdate(due)) + '.')
        elif want == 'sadece_asgari_odeme':
            mins = []
            for code, full, b in debt:
                mn, rmn = num(b.get('minPayment')), num(b.get('remainingMinPayment'))
                if code == 'TL' and rmn <= 0:
                    mins.append('Türk Lirası minimum ödemenizi yaptınız, teşekkür ederiz')
                elif code == 'TL' and rmn < mn:
                    mins.append('Türk Lirası için kalan minimum ödeme tutarınız ' + money(rmn, 'TL'))
                else:
                    mins.append(full + ' için ödenmesi gereken minimum tutar ' + money(mn, code))
            parts.append(intro + ' kartınıza ait ' + tdate(sd) + ' tarihinde kesilen ekstrede ' + '; '.join(mins) + '.')
            ds = due_sentence()
            if ds:
                parts.append(ds)
        else:
            first = True
            for code, full, b in debt:
                sdb, mn, rd, rmn = b.get('statementDebt'), b.get('minPayment'), b.get('remainingDebt'), b.get('remainingMinPayment')
                if code == 'TL':
                    if num(rmn) <= 0:
                        s = 'Türk Lirası borcunuz ' + money(sdb, 'TL') + ', kalan toplam borcunuz ' + cop(money(rd, 'TL')) + '. Minimum ödemenizi yaptığınız için teşekkür ederiz.'
                    elif num(rmn) >= num(mn):
                        s = 'Türk Lirası borcunuz ' + money(sdb, 'TL') + ', ödenmesi gereken minimum tutar ' + cop(money(mn, 'TL')) + '.'
                    else:
                        s = 'Türk Lirası borcunuz ' + money(sdb, 'TL') + ', ödenmesi gereken minimum tutar ' + money(mn, 'TL') + ', kalan toplam borcunuz ' + money(rd, 'TL') + ', kalan minimum ödeme tutarınız ' + cop(money(rmn, 'TL')) + '.'
                else:
                    s = full + ' borcunuz ' + money(sdb, code) + ', kalan toplam borcunuz ' + money(rd, code) + ', ödenmesi gereken minimum tutar ' + cop(money(mn, code)) + '.'
                if first:
                    s = intro + ' kartınıza ait ' + tdate(sd) + ' tarihinde kesilen ekstre ' + s
                    first = False
                parts.append(s)
            if clear:
                parts.append(join_tr(clear) + ' borcunuz bulunmamaktadır.')
            ds = due_sentence()
            if ds:
                parts.append(ds)
    return parts, nodebt

try:
    if isinstance(result, dict):
        d, api, res, ok = env(result)
        mode = str(vars.get('kb_mode') or 'ok')
        cur_slot = str(vars.get('reading_slot') or 'none')
        if mode != 'ok':
            d.clear()
            dg = str(vars.get('kb_digits') or '')
            if mode == 'amb4':
                msg = 'Bu son dört haneye sahip birden fazla kart var. Kartı seçmeden şunu aynen sor: "Son dört hanesi ' + l4w(dg[-4:]) + ' olan birden fazla kartınız var. Kartınızın son altı hanesini söyler misiniz?" Cevap gelince kart_borcu aracını son_haneler ile tekrar çağır.'
            elif mode == 'amb6':
                msg = 'Kartı seçmeden şunu aynen sor: "Son altı hanesi aynı olan birden fazla kartınız var. Kart numaranızı söyler misiniz?" Numarayı asla geri okuma; cevap gelince kart_borcu aracını son_haneler ile tekrar çağır.'
            elif mode == 'dupname':
                nm = str(vars.get('kb_name') or '')
                msg = 'Bu isimde birden fazla kart var. Müşteri son dört haneyi zaten söylediyse kart_borcu aracını son_haneler ile tekrar çağır; söylemediyse şunu aynen sor: "' + nm + ' isimli birden fazla kartınız var. Kartınızın son dört hanesini söyler misiniz?"'
            elif mode == 'supp':
                msg = 'Bu kart ek kart; borç sorgusu için uygun değil. Bu kart için borç sorgulayamadığını söyle ve başka bir kartını seçmesini iste. Bu bir deneme sayılır.'
            elif mode == 'nomatch':
                msg = 'Söylenen rakamlarla eşleşen bir kartı yok. Rakamları tekrar etmeden bu rakamlarla eşleşen bir kartı olmadığını söyle ve kartını tekrar sor: "' + str(vars.get('select_question') or '') + '" Bu bir deneme sayılır.'
            elif mode == 'partial':
                msg = 'Rakamlar eksik. Hiçbir rakamı kendin tamamlama; eksik kısmı ya da kartın son dört hanesinin tamamını söylemesini iste.'
            else:
                msg = 'Hangi kart olduğu belli değil. Şunu sor: "' + str(vars.get('select_question') or '') + '"'
            d['what_to_do_next'] = msg
            d['reading_slot'] = cur_slot
        elif not ok:
            d.clear()
            d['what_to_do_next'] = 'Bakiye servisi hata verdi. Hiçbir rakam söyleme ve şunu aynen söyle: "' + FAIL_GEN + '"'
            d['reading_slot'] = cur_slot
        else:
            cn = str(vars.get('kb_card') or '')
            cards = load_cards(vars)
            card = dict(cardNumber=cn, cardNumberLast4=str(api.get('cardNumberLast4') or cn[-4:]), productName=str(api.get('productName') or ''))
            for c in cards:
                if str(c.get('cardNumber')) == cn:
                    card = c
            want = str(vars.get('kb_want') or 'tum_bilgiler')
            parts, nodebt = build(api, card, vars, want)
            try:
                read = json.loads(vars.get('read_cards') or '[]')
            except Exception:
                read = []
            if cn not in read:
                read.append(cn)
            vars['read_cards'] = json.dumps(read)
            remaining = [c for c in cards if elig(c) and str(c.get('cardNumber')) not in read]
            seq = int(num(vars.get('reading_seq'))) + 1
            vars['reading_seq'] = str(seq)
            if remaining:
                parts.append('Başka bir kartınızın borcunu öğrenmek ister misiniz?')
                slot = 'A' if seq % 2 == 1 else 'B'
            elif nodebt:
                parts.append(MENU)
                slot = 'E'
            else:
                ot = offer_text(vars)
                if ot:
                    parts.append(ot)
                slot = 'A' if seq % 2 == 1 else 'B'
            text = ' '.join(p for p in parts if p)
            first_debt = 'TL'
            for code, key, full in CUR:
                blk = api.get(key)
                if isinstance(blk, dict) and num(blk.get('remainingDebt')) > 0:
                    first_debt = code
                    break
            vars['sel_card'] = cn
            vars['sel_label'] = intro_of(card) + ' kart'
            vars['sel_sd'] = str(api.get('statementDate') or '')
            vars['sel_currency'] = first_debt
            vars['sel_nodebt'] = 'yes' if nodebt else 'no'
            vars['speak_text'] = text
            vars['reading_slot'] = slot
            vars['offer_text'] = offer_text(vars)
            d.clear()
            d['speak_text'] = text
            d['reading_slot'] = slot
            d['what_to_do_next'] = 'Borç bilgisi müşteriye sistem tarafından şimdi okunuyor; sen okuma ve tekrar etme. Müşterinin cevabını bekle.'
except Exception:
    pass

