    if t:
        p.append(TENS[t])
    if o:
        p.append(ONES[o])
    return ' '.join(p)

def words(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    out = []
    for val, nm in ((10 ** 9, 'milyar'), (10 ** 6, 'milyon'), (1000, 'bin')):
        q, n = divmod(n, val)
        if q:
            out.append('bin' if (val == 1000 and q == 1) else words(q) + ' ' + nm)
