def w3(n):
    p = []
    h, r = divmod(int(n), 100)
    if h:
        p.append('yüz' if h == 1 else ONES[h] + ' yüz')
    t, o = divmod(r, 10)
    if t:
        p.append(TENS[t])
    if o:
        p.append(ONES[o])
    return ' '.join(p)

def words(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    out = []
    for val, nm in ((10 ** 9, 'milyar'), (10 ** 6, 'milyon'), (1000, 'bin')):
        q, n = divmod(n, val)
        if q:
            out.append('bin' if (val == 1000 and q == 1) else words(q) + ' ' + nm)
    if n:
        out.append(w3(n))
    return ' '.join(out)

def num(x):
    try:
        return float(x)
    except Exception:
        return 0.0

